import { parseEventLogs, encodeAbiParameters } from 'viem';

// src/errors.ts
var MuHavenError = class extends Error {
  constructor(message, cause) {
    super(message);
    this.cause = cause;
    this.name = "MuHavenError";
  }
};
var ConfigError = class extends MuHavenError {
  constructor(message) {
    super(message);
    this.name = "ConfigError";
  }
};
var NetworkError = class extends MuHavenError {
  constructor(expectedChainId, actualChainId) {
    super(`Chain mismatch: expected ${expectedChainId}, got ${actualChainId}`);
    this.name = "NetworkError";
  }
};
var EscrowNotFoundError = class extends MuHavenError {
  constructor(escrowId) {
    super(`Escrow ${escrowId} does not exist`);
    this.escrowId = escrowId;
    this.name = "EscrowNotFoundError";
  }
};
var EncryptionError = class extends MuHavenError {
  constructor(message, cause) {
    super(`Encryption failed: ${message}`, cause);
    this.name = "EncryptionError";
  }
};
var BatchSizeExceededError = class extends MuHavenError {
  constructor(requested, max) {
    super(`Batch size ${requested} exceeds max ${max}`);
    this.requested = requested;
    this.max = max;
    this.name = "BatchSizeExceededError";
  }
};
var DistributionNotStartedError = class extends MuHavenError {
  constructor(distributionId) {
    super(`Distribution ${distributionId} has not been started`);
    this.distributionId = distributionId;
    this.name = "DistributionNotStartedError";
  }
};
var DistributionAlreadyCompleteError = class extends MuHavenError {
  constructor(distributionId) {
    super(`Distribution ${distributionId} is already complete`);
    this.distributionId = distributionId;
    this.name = "DistributionAlreadyCompleteError";
  }
};
var EscrowIdsAlreadySetError = class extends MuHavenError {
  constructor(distributionId) {
    super(`Escrow IDs already set for distribution ${distributionId}`);
    this.distributionId = distributionId;
    this.name = "EscrowIdsAlreadySetError";
  }
};
var TxFailedError = class extends MuHavenError {
  /**
   * @param operation  Human-readable label for the failing call
   *                   (e.g. 'MuHavenEscrow.batchCreate').
   * @param txHash     Transaction hash if the tx was broadcast; undefined if
   *                   the failure happened before submission (encoding,
   *                   insufficient funds, rejected by wallet). Consumers
   *                   should check for `undefined` rather than a literal '0x'.
   */
  constructor(operation, txHash, cause) {
    super(
      txHash ? `Transaction failed for ${operation} (${txHash})` : `Transaction failed for ${operation} (not submitted)`,
      cause
    );
    this.operation = operation;
    this.txHash = txHash;
    this.name = "TxFailedError";
  }
};
var InvariantError = class extends MuHavenError {
  constructor(message, cause) {
    super(`Invariant violated: ${message}`, cause);
    this.name = "InvariantError";
  }
};

