// src/internal/batching.ts
function paginate(total, batchSize) {
  if (total <= 0) return [];
  if (batchSize <= 0) throw new Error(`batchSize must be > 0, got ${batchSize}`);
  const batches = [];
  for (let offset = 0; offset < total; offset += batchSize) {
    const size = Math.min(batchSize, total - offset);
    batches.push({ offset, size });
  }
  return batches;
}
function toEncryptedInput(raw, index = 0) {
  if (!raw || typeof raw !== "object") {
    throw new EncryptionError(`item[${index}] is not an object`);
  }
  const r = raw;
  if (r["ctHash"] === void 0) throw new EncryptionError(`item[${index}] missing ctHash`);
  if (r["securityZone"] === void 0) throw new EncryptionError(`item[${index}] missing securityZone`);
  if (r["utype"] === void 0) throw new EncryptionError(`item[${index}] missing utype`);
  if (r["signature"] === void 0) throw new EncryptionError(`item[${index}] missing signature`);
  const ctHash = typeof r["ctHash"] === "bigint" ? r["ctHash"] : BigInt(r["ctHash"]);
  const securityZone = Number(r["securityZone"]);
  const utype = Number(r["utype"]);
  const sigRaw = r["signature"];
  const signature = typeof sigRaw === "string" && sigRaw.startsWith("0x") ? sigRaw : `0x${sigRaw}`;
  return { ctHash, securityZone, utype, signature };
}
function encodeYieldGateResolverData(beneficiary) {
  return encodeAbiParameters([{ type: "address" }], [beneficiary]);
}

// src/internal/encryption.ts
async function buildAddressEncryptables(addresses) {
  const { Encryptable } = await import('@cofhe/sdk');
  return addresses.map((addr) => Encryptable.address(addr));
}
async function buildUint64Encryptable(value) {
  const { Encryptable } = await import('@cofhe/sdk');
  return Encryptable.uint64(value);
}
async function buildUint128Encryptable(value) {
  const { Encryptable } = await import('@cofhe/sdk');
  return Encryptable.uint128(value);
}
async function encryptAddresses(cofhe, addresses) {
  if (addresses.length === 0) return [];
  const items = await buildAddressEncryptables(addresses);
  let raw;
  try {
    raw = await cofhe.encryptInputs(items).execute();
  } catch (e) {
    throw new EncryptionError(`batch encrypt of ${addresses.length} addresses failed`, e);
  }
  if (raw.length !== addresses.length) {
    throw new EncryptionError(
      `expected ${addresses.length} encrypted results, got ${raw.length}`
    );
  }
  return raw.map((r, i) => toEncryptedInput(r, i));
}
async function encryptUint64(cofhe, value) {
  if (value < 0n) {
    throw new EncryptionError(`uint64 value must be >= 0, got ${value}`);
  }
  if (value > (1n << 64n) - 1n) {
    throw new EncryptionError(`uint64 value exceeds 2^64 - 1, got ${value}`);
  }
  const item = await buildUint64Encryptable(value);
  let raw;
  try {
    raw = await cofhe.encryptInputs([item]).execute();
  } catch (e) {
    throw new EncryptionError(`uint64 encrypt failed`, e);
  }
  const first = raw[0];
  if (first === void 0) throw new EncryptionError("no encrypted result returned");
  return toEncryptedInput(first, 0);
}
async function encryptUint128(cofhe, value) {
  if (value < 0n) {
    throw new EncryptionError(`uint128 value must be >= 0, got ${value}`);
  }
  if (value > (1n << 128n) - 1n) {
    throw new EncryptionError(`uint128 value exceeds 2^128 - 1, got ${value}`);
  }
  const item = await buildUint128Encryptable(value);
  let raw;
  try {
    raw = await cofhe.encryptInputs([item]).execute();
  } catch (e) {
    throw new EncryptionError(`uint128 encrypt failed`, e);
  }
  const first = raw[0];
  if (first === void 0) throw new EncryptionError("no encrypted result returned");
  return toEncryptedInput(first, 0);
}
async function writeAndWait(args) {
  const { publicClient, sender, address, abi, functionName, args: callArgs, operation } = args;
  let hash;
  try {
    hash = await sender.write({
      address,
      abi,
      functionName,
      args: callArgs
    });
  } catch (e) {
    throw new TxFailedError(operation, void 0, e);
  }
  let receipt;
  try {
    receipt = await publicClient.waitForTransactionReceipt({ hash });
  } catch (e) {
    throw new TxFailedError(operation, hash, e);
  }
  if (receipt.status !== "success") {
    throw new TxFailedError(operation, hash, new Error(`receipt status: ${receipt.status}`));
  }
  return { hash, logs: receipt.logs };
}
function parseEscrowCreatedIds(logs, escrowAbi, escrowAddress) {
  const parsed = parseEventLogs({
    abi: escrowAbi,
    eventName: "EscrowCreated",
    logs
  });
  const ids = [];
  for (const log of parsed) {
    if (log.address.toLowerCase() !== escrowAddress.toLowerCase()) continue;
    const args = log.args;
    ids.push(args.escrowId);
  }
  return ids;
}

// src/constants.ts
var MAX_BATCH_SIZE = 200;
var DEFAULT_BATCH_SIZE = 50;
var RATE_SCALE = 1000000n;

// src/escrows.ts
async function fetchAllInvestors(publicClient, registry, pageSize = 100) {
  const count = await publicClient.readContract({
    address: registry,
    abi: investorRegistryAbi,
    functionName: "investorCount"
  });
  const total = Number(count);
  if (total === 0) return [];
  const result = [];
  for (let offset = 0; offset < total; offset += pageSize) {
    const limit = Math.min(pageSize, total - offset);
    const page = await publicClient.readContract({
      address: registry,
      abi: investorRegistryAbi,
      functionName: "getInvestorsPaginated",
      args: [BigInt(offset), BigInt(limit)]
    });
    result.push(...page);
  }
  return result;
}
async function batchCreateEscrows(args) {
  const { publicClient, sender, cofheClient, muhavenEscrow, yieldGate, investors } = args;
  if (investors.length === 0) throw new ConfigError("investors array is empty");
  if (investors.length > MAX_BATCH_SIZE) {
    throw new BatchSizeExceededError(investors.length, MAX_BATCH_SIZE);
  }
  const encrypted = await encryptAddresses(cofheClient, investors);
  const resolverData = investors.map(encodeYieldGateResolverData);
  const owners = encrypted.map((e) => ({
    ctHash: e.ctHash,
    securityZone: e.securityZone,
    utype: e.utype,
    signature: e.signature
  }));
  const { hash, logs } = await writeAndWait({
    publicClient,
    sender,
    address: muhavenEscrow,
    abi: muhavenEscrowAbi,
    functionName: "batchCreate",
    args: [owners, yieldGate, resolverData],
    operation: "MuHavenEscrow.batchCreate"
  });
  const escrowIds = parseEscrowCreatedIds(logs, muhavenEscrowAbi, muhavenEscrow);
  if (escrowIds.length !== investors.length) {
    throw new InvariantError(
      `MuHavenEscrow.batchCreate emitted ${escrowIds.length} EscrowCreated events for ${investors.length} inputs`
    );
  }
  return { escrowIds, txHash: hash };
}
async function createYieldEscrowsFlow(args) {
  const {
    publicClient,
    sender,
    cofheClient,
    muhavenEscrow,
    yieldGate,
    investorRegistry,
    batchSize,
    onProgress
  } = args;
  if (batchSize <= 0 || batchSize > MAX_BATCH_SIZE) {
    throw new BatchSizeExceededError(batchSize, MAX_BATCH_SIZE);
  }
  const investors = await fetchAllInvestors(publicClient, investorRegistry);
  if (investors.length === 0) {
    return { escrowIds: [], txHashes: [] };
  }
  const batches = paginate(investors.length, batchSize);
  const escrowIds = [];
  const txHashes = [];
  for (let i = 0; i < batches.length; i++) {
    const batch = batches[i];
    const slice = investors.slice(batch.offset, batch.offset + batch.size);
    onProgress?.({
      stage: "encrypt",
      current: i,
      total: batches.length,
      message: `Encrypting batch ${i + 1}/${batches.length} (${slice.length} investors)`
    });
    const { escrowIds: ids, txHash } = await batchCreateEscrows({
      publicClient,
      sender,
      cofheClient,
      muhavenEscrow,
      yieldGate,
      investors: slice
    });
    escrowIds.push(...ids);
    txHashes.push(txHash);
    onProgress?.({
      stage: "batchCreate",
      current: i + 1,
      total: batches.length,
      message: `Created ${ids.length} escrows (batch ${i + 1}/${batches.length})`,
      txHash
    });
  }
  return { escrowIds, txHashes };
}

