// src/yield.ts
var DistributionStatus = {
  Pending: 0,
  InProgress: 1,
  Complete: 2
};
async function getDistribution(publicClient, yieldDistributor, distributionId) {
  const raw = await publicClient.readContract({
    address: yieldDistributor,
    abi: yieldDistributorAbi,
    functionName: "getDistribution",
    args: [distributionId]
  });
  return {
    token: raw[0],
    investorCount: raw[3],
    processedCount: raw[4],
    escrowsCreated: raw[5],
    status: raw[6]
  };
}
async function startDistributionFlow(args) {
  const { publicClient, sender, cofheClient, yieldDistributor, totalYield, onProgress } = args;
  if (totalYield <= 0n) throw new ConfigError(`totalYield must be > 0, got ${totalYield}`);
  onProgress?.({
    stage: "encrypt",
    current: 0,
    total: 1,
    message: "Encrypting total yield amount"
  });
  const enc = await encryptUint64(cofheClient, totalYield);
  const { hash, logs } = await writeAndWait({
    publicClient,
    sender,
    address: yieldDistributor,
    abi: yieldDistributorAbi,
    functionName: "startDistribution",
    args: [{
      ctHash: enc.ctHash,
      securityZone: enc.securityZone,
      utype: enc.utype,
      signature: enc.signature
    }],
    operation: "YieldDistributor.startDistribution"
  });
  const { parseEventLogs: parseEventLogs4 } = await import('viem');
  const events = parseEventLogs4({
    abi: yieldDistributorAbi,
    eventName: "DistributionStarted",
    logs
  });
  const match = events.find(
    (log) => log.address.toLowerCase() === yieldDistributor.toLowerCase()
  );
  if (!match) {
    throw new InvariantError("YieldDistributor.startDistribution emitted no DistributionStarted event");
  }
  const distributionId = match.args.distributionId;
  onProgress?.({
    stage: "startDistribution",
    current: 1,
    total: 1,
    message: `Distribution ${distributionId} started`,
    txHash: hash
  });
  return { distributionId, txHash: hash };
}
async function setEscrowIdsFlow(args) {
  const { publicClient, sender, yieldDistributor, distributionId, escrowIds, onProgress } = args;
  const { hash } = await writeAndWait({
    publicClient,
    sender,
    address: yieldDistributor,
    abi: yieldDistributorAbi,
    functionName: "setEscrowIds",
    args: [distributionId, escrowIds],
    operation: "YieldDistributor.setEscrowIds"
  });
  onProgress?.({
    stage: "setEscrowIds",
    current: 1,
    total: 1,
    message: `Attached ${escrowIds.length} escrowIds to distribution ${distributionId}`,
    txHash: hash
  });
  return hash;
}
async function processUntilCompleteFlow(args) {
  const { publicClient, sender, yieldDistributor, distributionId, batchSize, onProgress } = args;
  if (batchSize <= 0 || batchSize > MAX_BATCH_SIZE) {
    throw new BatchSizeExceededError(batchSize, MAX_BATCH_SIZE);
  }
  const count = await publicClient.readContract({
    address: yieldDistributor,
    abi: yieldDistributorAbi,
    functionName: "distributionCount"
  });
  if (distributionId === 0n || distributionId > count) {
    throw new DistributionNotStartedError(distributionId);
  }
  const initial = await getDistribution(publicClient, yieldDistributor, distributionId);
  if (initial.status === DistributionStatus.Complete) {
    throw new DistributionAlreadyCompleteError(distributionId);
  }
  const total = Number(initial.investorCount);
  const txHashes = [];
  let batchesProcessed = 0;
  while (true) {
    const state = await publicClient.readContract({
      address: yieldDistributor,
      abi: yieldDistributorAbi,
      functionName: "isDistributionComplete",
      args: [distributionId]
    });
    if (state) break;
    const { hash } = await writeAndWait({
      publicClient,
      sender,
      address: yieldDistributor,
      abi: yieldDistributorAbi,
      functionName: "processBatch",
      args: [distributionId, BigInt(batchSize)],
      operation: "YieldDistributor.processBatch"
    });
    txHashes.push(hash);
    batchesProcessed += 1;
    const updated = await getDistribution(publicClient, yieldDistributor, distributionId);
    onProgress?.({
      stage: "processBatch",
      current: Number(updated.processedCount),
      total,
      message: `Processed ${updated.processedCount}/${total} investors`,
      txHash: hash
    });
  }
  return { batchesProcessed, txHashes };
}
async function grantAdminDecryptFlow(args) {
  const { publicClient, sender, yieldDistributor, distributionId, viewer, onProgress } = args;
  const { hash } = await writeAndWait({
    publicClient,
    sender,
    address: yieldDistributor,
    abi: yieldDistributorAbi,
    functionName: "grantYieldDecryptAccess",
    args: [distributionId, viewer],
    operation: "YieldDistributor.grantYieldDecryptAccess"
  });
  onProgress?.({
    stage: "grantAdminDecrypt",
    current: 1,
    total: 1,
    message: `Granted decrypt access on distribution ${distributionId} to ${viewer}`,
    txHash: hash
  });
  return hash;
}
async function fundEscrowsFlow(args) {
  const { publicClient, sender, yieldDistributor, distributionId, escrowIds, batchSize, onProgress } = args;
  if (escrowIds.length === 0) throw new ConfigError("escrowIds is empty");
  const count = await publicClient.readContract({
    address: yieldDistributor,
    abi: yieldDistributorAbi,
    functionName: "distributionCount"
  });
  if (distributionId === 0n || distributionId > count) {
    throw new DistributionNotStartedError(distributionId);
  }
  const before = await getDistribution(publicClient, yieldDistributor, distributionId);
  if (before.status === DistributionStatus.Complete) {
    throw new DistributionAlreadyCompleteError(distributionId);
  }
  if (before.investorCount !== BigInt(escrowIds.length)) {
    throw new ConfigError(
      `escrowIds length ${escrowIds.length} != investorCount ${before.investorCount}`
    );
  }
  const existing = await publicClient.readContract({
    address: yieldDistributor,
    abi: yieldDistributorAbi,
    functionName: "getEscrowIds",
    args: [distributionId]
  });
  const txHashesBeforeProcess = [];
  if (existing.length === 0) {
    const setTx = await setEscrowIdsFlow({
      publicClient,
      sender,
      yieldDistributor,
      distributionId,
      escrowIds,
      onProgress
    });
    txHashesBeforeProcess.push(setTx);
  } else {
    const matches = existing.length === escrowIds.length && existing.every((id, i) => id === escrowIds[i]);
    if (!matches) {
      throw new EscrowIdsAlreadySetError(distributionId);
    }
    onProgress?.({
      stage: "setEscrowIds",
      current: 1,
      total: 1,
      message: `Resuming distribution ${distributionId}: ${existing.length} escrowIds already attached`
    });
  }
  const { batchesProcessed, txHashes } = await processUntilCompleteFlow({
    publicClient,
    sender,
    yieldDistributor,
    distributionId,
    batchSize,
    onProgress
  });
  return {
    batchesProcessed,
    txHashes: [...txHashesBeforeProcess, ...txHashes]
  };
}

// src/claim.ts
async function claimYieldFlow(args) {
  const { publicClient, sender, muhavenEscrow, escrowId, onProgress } = args;
  const { hash } = await writeAndWait({
    publicClient,
    sender,
    address: muhavenEscrow,
    abi: muhavenEscrowAbi,
    functionName: "redeem",
    args: [escrowId],
    operation: "MuHavenEscrow.redeem"
  });
  onProgress?.({
    stage: "redeem",
    current: 1,
    total: 1,
    message: `Redeemed escrow ${escrowId}`,
    txHash: hash
  });
  return hash;
}
async function claimYieldBatchFlow(args) {
  const { publicClient, sender, muhavenEscrow, escrowIds, onProgress } = args;
  if (escrowIds.length === 0) throw new ConfigError("escrowIds is empty");
  if (escrowIds.length > MAX_BATCH_SIZE) {
    throw new BatchSizeExceededError(escrowIds.length, MAX_BATCH_SIZE);
  }
  const { hash } = await writeAndWait({
    publicClient,
    sender,
    address: muhavenEscrow,
    abi: muhavenEscrowAbi,
    functionName: "redeemMultiple",
    args: [escrowIds],
    operation: "MuHavenEscrow.redeemMultiple"
  });
  onProgress?.({
    stage: "redeem",
    current: escrowIds.length,
    total: escrowIds.length,
    message: `Redeemed ${escrowIds.length} escrows`,
    txHash: hash
  });
  return hash;
}

// src/client.ts
var MuHavenClient = class {
  constructor(config) {
    if (!config.publicClient) throw new ConfigError("publicClient is required");
    if (!config.sender) throw new ConfigError("sender is required");
    if (!config.cofheClient) throw new ConfigError("cofheClient is required");
    if (!config.addresses) throw new ConfigError("addresses is required");
    const required = [
      "muhavenEscrow",
      "yieldDistributor",
      "investorRegistry",
      "yieldGate"
    ];
    for (const k of required) {
      if (!config.addresses[k]) throw new ConfigError(`addresses.${k} is required`);
    }
    this.publicClient = config.publicClient;
    this.sender = config.sender;
    this.cofheClient = config.cofheClient;
    this.addresses = config.addresses;
    this.expectedChainId = config.expectedChainId;
    this.defaultBatchSize = config.defaultBatchSize ?? DEFAULT_BATCH_SIZE;
    if (this.defaultBatchSize <= 0 || this.defaultBatchSize > MAX_BATCH_SIZE) {
      throw new ConfigError(
        `defaultBatchSize must be in (0, ${MAX_BATCH_SIZE}], got ${this.defaultBatchSize}`
      );
    }
  }
  /** Read the connected sender's address. */
  getAccount() {
    return this.sender.address;
  }
  /**
   * Validate public client + sender are on the expected chain.
   * Throws NetworkError on mismatch. No-op if expectedChainId is unset.
   */
  async validateNetwork() {
    if (this.expectedChainId === void 0) return;
    const pubChainId = await this.publicClient.getChainId();
    if (pubChainId !== this.expectedChainId) {
      throw new NetworkError(this.expectedChainId, pubChainId);
    }
    const senderChainId = await this.sender.getChainId();
    if (senderChainId !== this.expectedChainId) {
      throw new NetworkError(this.expectedChainId, senderChainId);
    }
  }
  // ── Core methods (implemented in later 19C subtasks) ────────────────
  /**
   * Create a yield escrow for every registered investor.
   *
   * Pipeline per batch:
   *   1. Batch-encrypt K investor addresses via CoFHE (shared ZK proof).
   *   2. Submit `MuHavenEscrow.batchCreate(owners, yieldGate, resolverData)`.
   *   3. Parse `EscrowCreated` events from the receipt to collect escrowIds.
   *
   * The returned `escrowIds` array preserves the order of the investor registry
   * (which is what YieldDistributor.setEscrowIds expects).
   */
  async createYieldEscrows(opts) {
    const batchSize = opts?.batchSize ?? this.defaultBatchSize;
    return createYieldEscrowsFlow({
      publicClient: this.publicClient,
      sender: this.sender,
      cofheClient: this.cofheClient,
      muhavenEscrow: this.addresses.muhavenEscrow,
      yieldGate: this.addresses.yieldGate,
      investorRegistry: this.addresses.investorRegistry,
      batchSize,
      onProgress: opts?.onProgress
    });
  }
  /**
   * Attach `escrowIds` to a distribution and drive processBatch() until the
   * distribution completes. Each iteration funds up to `batchSize` escrows
   * via YieldDistributor → MuHavenEscrow.fundFrom.
   */
  async fundEscrows(distributionId, escrowIds, opts) {
    const batchSize = opts?.batchSize ?? this.defaultBatchSize;
    const { batchesProcessed, txHashes } = await fundEscrowsFlow({
      publicClient: this.publicClient,
      sender: this.sender,
      yieldDistributor: this.addresses.yieldDistributor,
      distributionId,
      escrowIds,
      batchSize,
      onProgress: opts?.onProgress
    });
    return { distributionId, batchesProcessed, txHashes };
  }
  /** Redeem a single escrow. Called by investors from the claim UI. */
  async claimYield(escrowId, opts) {
    return claimYieldFlow({
      publicClient: this.publicClient,
      sender: this.sender,
      muhavenEscrow: this.addresses.muhavenEscrow,
      escrowId,
      onProgress: opts?.onProgress
    });
  }
  /**
   * Redeem up to MAX_BATCH_SIZE escrows in a single tx via redeemMultiple.
   * On-chain semantics: non-existent IDs are silently skipped.
   */
  async claimYieldBatch(escrowIds, opts) {
    return claimYieldBatchFlow({
      publicClient: this.publicClient,
      sender: this.sender,
      muhavenEscrow: this.addresses.muhavenEscrow,
      escrowIds,
      onProgress: opts?.onProgress
    });
  }
  /**
   * Start a new distribution with the issuer's plaintext yield amount.
   * The amount is encrypted SDK-side before submission.
   *
   * **Pre-flight setup (caller responsibility):**
   *   - The issuer wallet must hold at least `totalYield` units of PUSDC.
   *   - The issuer must have granted YieldDistributor operator access via
   *     `pusdc.setOperator(yieldDistributor, expiry)`. Without this,
   *     YieldDistributor's `confidentialTransferFrom` pull call reverts.
   *   - The investor registry must be non-empty (contract rejects zero
   *     `investorCount` with `NoInvestors`).
   */
  async startDistribution(totalYield, opts) {
    return startDistributionFlow({
      publicClient: this.publicClient,
      sender: this.sender,
      cofheClient: this.cofheClient,
      yieldDistributor: this.addresses.yieldDistributor,
      totalYield,
      onProgress: opts?.onProgress
    });
  }
  /**
   * Full pipeline convenience: encrypt totalYield → startDistribution →
   * createYieldEscrows → fundEscrows. Calls progress callback at every stage.
   *
   * Use this when the caller just wants "distribute N PUSDC across all
   * registered investors" without managing distributionId bookkeeping.
   *
   * **Pre-flight setup (caller responsibility):** see `startDistribution`
   * JSDoc — the issuer must hold PUSDC and have set an operator approval
   * for YieldDistributor before invoking.
   */
  async distributeYield(totalYield, opts) {
    const { distributionId, txHash: startTx } = await this.startDistribution(
      totalYield,
      { onProgress: opts?.onProgress }
    );
    const { escrowIds, txHashes: createTxHashes } = await this.createYieldEscrows({
      batchSize: opts?.batchSize,
      onProgress: opts?.onProgress
    });
    const { txHashes: fundTxHashes } = await this.fundEscrows(
      distributionId,
      escrowIds,
      { batchSize: opts?.batchSize, onProgress: opts?.onProgress }
    );
    return {
      distributionId,
      escrowIds,
      createTxHashes: [startTx, ...createTxHashes],
      fundTxHashes
    };
  }
  /**
   * Grant `viewer` permit-based decrypt access to a distribution's encrypted
   * yield aggregates (`encTotalYield` and `encPerInvestorYield`). Issued via
   * plain `FHE.allow` on-chain — no async decrypt tasks.
   *
   * After the tx confirms, `viewer` can run
   * `cofheClient.decryptForView(ctHash).withPermit().execute()` on either
   * handle to read the plaintext.
   *
   * **Caller must be the YieldDistributor owner.** Non-owner calls revert
   * with `OnlyOwner` (surfaced as `TxFailedError`).
   *
   * @param distributionId  ID returned by startDistribution()
   * @param viewer          Address to grant decrypt-view access to
   */
  async grantAdminDecrypt(distributionId, viewer, opts) {
    return grantAdminDecryptFlow({
      publicClient: this.publicClient,
      sender: this.sender,
      yieldDistributor: this.addresses.yieldDistributor,
      distributionId,
      viewer,
      onProgress: opts?.onProgress
    });
  }
};
/** Re-exported for consumers that want to introspect distribution state. */
MuHavenClient.DistributionStatus = DistributionStatus;

// src/sender.ts
function walletClientToSender(walletClient) {
  const account = walletClient.account;
  if (!account) {
    throw new Error("walletClientToSender: walletClient has no account");
  }
  return {
    address: account.address,
    getChainId: () => walletClient.getChainId(),
    write: async ({ address, abi, functionName, args }) => {
      return walletClient.writeContract({
        account,
        chain: walletClient.chain,
        address,
        abi,
        functionName,
        args
      });
    }
  };
}

